/* ─── Portfolio detail page: two-column layout with sticky sidebar ─────────── */
.post-detail-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
  align-items: start;
}
@media (min-width: 1024px) {
  .post-detail-grid {
    grid-template-columns: 1fr 320px;
  }
}
.post-detail-main {
  min-width: 0;
}
.post-detail-sidebar {
  display: none;
}
@media (min-width: 1024px) {
  .post-detail-sidebar {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
    position: sticky;
    top: 5rem;
    max-height: calc(100vh - 6rem);
    overflow-y: auto;
  }
}
/* Sidebar cards */
.post-sidebar-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 0.875rem;
  padding: 1.125rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.post-sidebar-section-title {
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: #94a3b8;
  margin: 0;
}
/* Sidebar author */
.post-sidebar-author {
  display: flex;
  align-items: center;
  gap: 0.625rem;
}
.post-sidebar-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
  background: #f1f5f9;
}
.post-sidebar-author-name {
  font-size: 0.82rem;
  font-weight: 700;
  color: #111;
  margin: 0;
}
.post-sidebar-author-sub {
  font-size: 0.72rem;
  color: #94a3b8;
  margin: 0;
}
/* Sidebar tags */
.post-sidebar-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}
/* Sidebar related */
.post-sidebar-related-list {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}
.post-sidebar-related-item {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  text-decoration: none;
  padding: 0.5rem 0.625rem;
  border-radius: 0.625rem;
  transition: background 0.15s;
}
.post-sidebar-related-item:hover {
  background: #f8fafc;
}
.post-sidebar-related-logo {
  width: 28px;
  height: 28px;
  border-radius: 0.375rem;
  object-fit: cover;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  flex-shrink: 0;
}
.post-sidebar-related-name {
  font-size: 0.78rem;
  font-weight: 700;
  color: #111;
  margin: 0;
  line-height: 1.3;
}
.post-sidebar-related-excerpt {
  font-size: 0.7rem;
  color: #94a3b8;
  margin: 0;
  line-height: 1.4;
}
/* Section header inside content */
.post-section-divider {
  border: none;
  border-top: 1px solid #e2e8f0;
  margin: 2rem 0 0.5rem;
}
.post-section-header {
  font-size: 1rem;
  font-weight: 700;
  color: #111;
  margin: 0 0 0.75rem;
  letter-spacing: -0.01em;
}
/* Wrapper for the full-width topnav + two-col grid */
.post-detail-wrap {
  max-width: 72rem;
  margin: 0 auto;
  padding: 3rem 1.5rem 6rem;
  font-family: var(--font-inter), system-ui, sans-serif;
}
